/* Banco de perguntas: Termologia. Mesmos campos dos outros bancos. */
window.BANKS=window.BANKS||{};
window.BANKS.termo=[{"id": "t001", "an": "agitacao", "t": "tm", "q": "O que a temperatura de um corpo mede?", "o": ["O grau de agitação das partículas que formam o corpo.", "A quantidade total de calor guardada no corpo.", "A massa do corpo.", "A cor do corpo."], "a": 0, "h": "Pense no movimento das moléculas.", "e": "A temperatura está ligada à energia cinética média de agitação das partículas. Quanto mais agitadas, maior a temperatura.", "x": {"1": "Calor guardado não é o que a temperatura mede: calor é energia em trânsito.", "2": "A massa é outra grandeza. Dois corpos com a mesma temperatura podem ter massas bem diferentes.", "3": "A cor não indica a temperatura medida. A temperatura vem da agitação das partículas."}, "n": 1}, {"id": "t002", "an": "calor_temp", "t": "tm", "q": "Qual é a diferença entre calor e temperatura?", "o": ["Calor é energia em trânsito por diferença de temperatura; temperatura mede o grau de agitação das partículas.", "São a mesma coisa.", "Calor mede o grau de agitação; temperatura é energia em trânsito.", "Calor só existe em corpos quentes e temperatura só em corpos frios."], "a": 0, "h": "Um é energia que passa; o outro é uma medida.", "e": "Calor é a energia que passa de um corpo para outro quando há diferença de temperatura. A temperatura mede o estado de agitação das partículas.", "x": {"1": "São grandezas diferentes: calor é energia que passa, temperatura é uma medida do estado de agitação.", "2": "Aqui os conceitos estão trocados. Quem mede a agitação é a temperatura.", "3": "Todo corpo tem temperatura, e o calor só aparece quando há troca entre corpos com temperaturas diferentes."}, "n": 2}, {"id": "t003", "t": "tm", "q": "Em que sentido o calor flui espontaneamente?", "o": ["Do corpo de maior temperatura para o de menor temperatura.", "Do corpo de menor para o de maior temperatura.", "Do corpo de maior massa para o de menor massa.", "Sempre do sólido para o líquido."], "a": 0, "h": "Pense em uma xícara quente sobre a mesa.", "e": "O calor flui espontaneamente do corpo mais quente para o mais frio até o equilíbrio térmico.", "x": {"1": "Isso só ocorre com ajuda externa, como em uma geladeira. Espontaneamente, o calor vai do mais quente para o mais frio.", "2": "A massa não decide o sentido do fluxo. Quem decide é a diferença de temperatura.", "3": "O estado físico não determina o sentido do calor."}, "an": "equil_termico", "n": 1}, {"id": "t004", "an": "equil_termico", "t": "tm", "q": "O que significa dizer que dois corpos estão em equilíbrio térmico?", "o": ["Eles têm a mesma temperatura e não trocam calor entre si.", "Eles têm a mesma massa.", "Eles têm o mesmo calor guardado.", "Um deles perdeu todo o calor."], "a": 0, "h": "Depois de algum tempo em contato, o que acontece com as temperaturas?", "e": "No equilíbrio térmico as temperaturas se igualam, e o fluxo líquido de calor cessa.", "x": {"1": "Corpos de massas diferentes podem estar em equilíbrio térmico. O que importa é a temperatura.", "2": "Calor não fica guardado no corpo. Equilíbrio significa igualdade de temperatura.", "3": "Nenhum corpo perde todo o calor. Eles apenas igualam as temperaturas."}, "n": 2}, {"id": "t005", "an": "escalas", "t": "tm", "q": "Verdadeiro ou falso: na escala Celsius, a água ferve a 100 °C e congela a 0 °C ao nível do mar.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "São os pontos fixos da escala.", "e": "Os pontos fixos da escala Celsius são 0 °C (fusão do gelo) e 100 °C (ebulição da água) à pressão normal.", "v": 1, "f": "escalas", "x": {"1": "Ao nível do mar, a água congela a 0 °C e ferve a 100 °C na escala Celsius. A afirmação é verdadeira."}, "n": 1}, {"id": "t006", "an": "escalas", "t": "tm", "q": "Qual é a relação entre a escala Kelvin e a Celsius?", "o": ["TK = TC + 273", "TK = TC − 273", "TK = 1,8 · TC + 32", "TK = TC · 273"], "a": 0, "h": "O zero absoluto é −273 °C.", "e": "A conversão usada é TK = TC + 273. Assim 0 °C corresponde a 273 K.", "f": "escalas", "x": {"1": "O sinal está trocado. Para obter Kelvin, soma-se 273 ao valor em Celsius.", "2": "Essa é a forma da conversão de Celsius para Fahrenheit (TF = 1,8·TC + 32), não a de Kelvin.", "3": "Não se multiplica por 273. A relação é uma soma."}, "n": 1}, {"id": "t007", "an": "escalas", "t": "tm", "q": "O zero absoluto (0 K) corresponde, aproximadamente, a:", "o": ["−273 °C", "0 °C", "−100 °C", "273 °C"], "a": 0, "h": "É a menor temperatura possível.", "e": "Pela relação TK = TC + 273, 0 K equivale a cerca de −273 °C.", "x": {"1": "0 °C é o ponto de congelamento da água. O zero absoluto está bem abaixo.", "2": "−100 °C é uma temperatura mais alta que o zero absoluto.", "3": "O sinal está errado: 273 °C é bem quente. O zero absoluto é −273 °C."}, "n": 1}, {"id": "t008", "an": "escalas", "t": "tm", "q": "Qual é a conversão entre Celsius (TC) e Fahrenheit (TF)?", "o": ["TC/5 = (TF − 32)/9", "TC/9 = (TF − 32)/5", "TC = TF − 32", "TC/5 = TF/9"], "a": 0, "h": "A água congela a 0 °C = 32 °F e ferve a 100 °C = 212 °F.", "e": "A razão entre variações é 5 para 9: TC/5 = (TF − 32)/9.", "f": "escalas", "x": {"1": "Os denominadores estão trocados: o certo é TC/5 = (TF − 32)/9.", "2": "Os intervalos têm tamanhos diferentes, então não basta subtrair 32.", "3": "Falta o termo −32 no Fahrenheit: o correto é (F − 32)/9."}, "n": 1}, {"id": "t009", "an": "escalas", "t": "tm", "q": "Uma variação de temperatura de 10 °C corresponde, na escala Kelvin, a uma variação de:", "o": ["10 K", "283 K", "263 K", "18 K"], "a": 0, "h": "As escalas têm o mesmo tamanho de grau.", "e": "Os intervalos de 1 °C e 1 K são iguais. Só o ponto de partida é diferente.", "x": {"1": "Somou-se 273 a uma variação. Isso só vale para valores de temperatura, não para variações.", "2": "Subtrair 273 de uma variação também é erro. Variações são iguais em °C e em K.", "3": "18 seria a variação em °F (fator 1,8), não em K."}, "n": 1}, {"id": "t010", "t": "tm", "q": "Um termômetro clínico de mercúrio funciona porque o mercúrio:", "o": ["Dilata quando a temperatura aumenta.", "Fica mais pesado quando esquenta.", "Muda de cor.", "Congela perto do corpo."], "a": 0, "h": "Pense no que ocorre com o volume do líquido.", "e": "O mercúrio dilata de modo regular com a temperatura, e a altura da coluna indica o valor medido.", "x": {"1": "O mercúrio não fica mais pesado: sua massa não muda. O volume é que aumenta.", "2": "A cor não muda e não é o que indica a temperatura.", "3": "O mercúrio congela a cerca de −39 °C, muito longe da temperatura do corpo."}, "an": "termometro", "n": 1}, {"id": "t011", "an": "calc_t011", "t": "tm", "q": "A temperatura de 300 K corresponde a quantos graus Celsius?", "o": ["27 °C", "573 °C", "−573 °C", "300 °C"], "a": 0, "h": "TC = TK − 273.", "e": "TC = 300 − 273 = 27 °C.", "c": 1, "x": {"1": "Foi somado 273 em vez de subtrair. TC = TK − 273.", "2": "TC = TK − 273 não dá número negativo aqui. Confira o sinal.", "3": "300 é o valor em Kelvin. Para converter, subtraia 273."}, "n": 1}, {"id": "t012", "an": "calc_t012", "t": "tm", "q": "Qual é a temperatura, em °C, correspondente a 68 °F?", "o": ["20 °C", "36 °C", "40 °C", "68 °C"], "a": 0, "h": "TC/5 = (TF − 32)/9.", "e": "TC/5 = (68 − 32)/9 = 4, então TC = 20 °C.", "c": 1, "x": {"1": "36 não resulta de (68 − 32)/1,8. Esse cálculo dá 20.", "2": "40 não vem da fórmula TC/5 = (TF − 32)/9.", "3": "68 é o valor em °F, não em °C. É preciso converter."}, "n": 2}, {"id": "t013", "an": "trilhos", "t": "dl", "q": "O que acontece, em geral, com as dimensões de um sólido quando ele é aquecido?", "o": ["Elas aumentam (dilatação).", "Elas diminuem.", "Ficam sempre iguais.", "Só a massa aumenta."], "a": 0, "h": "As partículas vibram mais e ocupam mais espaço.", "e": "Com o aquecimento a agitação aumenta e o corpo ocupa mais espaço: ocorre a dilatação térmica.", "x": {"1": "Em geral, os sólidos dilatam com o aquecimento e não encolhem.", "2": "As dimensões mudam, embora pouco.", "3": "A massa não muda com a temperatura. O que cresce é o tamanho."}, "n": 1}, {"id": "t014", "t": "dl", "q": "Por que há pequenos vãos entre os trilhos de uma ferrovia?", "o": ["Para permitir que os trilhos dilatem no calor sem se deformar.", "Para economizar aço.", "Para facilitar a limpeza.", "Para o trem andar mais rápido."], "a": 0, "h": "Pense em um dia muito quente.", "e": "Se não houvesse folga, a dilatação deformaria os trilhos nos dias quentes.", "x": {"1": "O vão não tem a ver com economia de material.", "2": "A limpeza não é o motivo. O motivo é a dilatação.", "3": "A velocidade do trem não depende dos vãos."}, "an": "trilhos", "n": 1}, {"id": "t015", "an": "dil_linear", "t": "dl", "q": "A expressão da dilatação linear de uma barra é:", "o": ["ΔL = L₀ · α · ΔT", "ΔL = L₀ + α + ΔT", "ΔL = α / (L₀ · ΔT)", "ΔL = L₀ · ΔT / α"], "a": 0, "h": "A variação do comprimento é proporcional ao comprimento inicial e à variação de temperatura.", "e": "A variação de comprimento é ΔL = L₀·α·ΔT, em que α é o coeficiente de dilatação linear.", "x": {"1": "Não se somam as grandezas: a dilatação é um produto L₀ · α · ΔT.", "2": "α não pode estar no denominador, porque a dilatação cresce com α.", "3": "α deve multiplicar, não dividir. Quanto maior α, maior a dilatação."}, "n": 1}, {"id": "t016", "an": "dil_coef", "t": "dl", "q": "Verdadeiro ou falso: o coeficiente de dilatação superficial (β) é, aproximadamente, o dobro do linear (α).", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Em duas dimensões, a dilatação conta duas vezes.", "e": "Para sólidos isotrópicos, β ≈ 2α e o volumétrico γ ≈ 3α.", "v": 1, "x": {"1": "β ≈ 2α, e γ ≈ 3α. A afirmação é verdadeira."}, "n": 1}, {"id": "t017", "t": "dl", "q": "Se uma chapa metálica com um furo é aquecida, o que acontece com o tamanho do furo?", "o": ["Ele aumenta, como se fosse feito do mesmo material da chapa.", "Ele diminui.", "Ele não muda.", "Ele desaparece."], "a": 0, "h": "O furo dilata como o material que o cerca.", "e": "O furo se comporta como se fosse preenchido pelo material da chapa e, por isso, aumenta com o aquecimento.", "x": {"1": "O furo se dilata junto com o material. Ele não encolhe.", "2": "A dilatação acontece em todas as direções, inclusive nas bordas do furo.", "3": "O furo não some: ele só aumenta."}, "an": "furo", "n": 2}, {"id": "t018", "an": "tampa", "t": "dl", "q": "Por que uma tampa metálica emperrada de um vidro pode ser solta passando-a sob água quente?", "o": ["Porque o metal dilata mais que o vidro e a tampa se afrouxa.", "Porque a água dissolve a tampa.", "Porque o vidro encolhe.", "Porque a água lubrifica a rosca, sem relação com a temperatura."], "a": 0, "h": "Compare os coeficientes de dilatação do metal e do vidro.", "e": "O metal costuma ter maior coeficiente de dilatação que o vidro, então a tampa dilata mais e solta.", "x": {"1": "A água não dissolve o metal.", "2": "O vidro também dilata, mas bem menos que o metal.", "3": "Se fosse só lubrificação, a água fria também serviria. O efeito aqui é térmico."}, "n": 2}, {"id": "t019", "t": "dl", "q": "Um termostato bimetálico usa duas lâminas de metais diferentes unidas. Ele funciona porque:", "o": ["Os dois metais dilatam de modo diferente e a lâmina se curva.", "Os dois metais derretem juntos.", "Um dos metais não dilata nunca.", "A lâmina fica mais pesada."], "a": 0, "h": "Coeficientes diferentes causam curvatura.", "e": "Com o aquecimento, o metal de maior coeficiente dilata mais, e a lâmina se curva, abrindo ou fechando um circuito.", "x": {"1": "Eles não derretem nessas temperaturas.", "2": "Todo metal dilata. A diferença está na intensidade.", "3": "A massa da lâmina não muda."}, "an": "bimetal", "n": 3}, {"id": "t020", "t": "dl", "q": "Qual é o comportamento anômalo da água entre 0 °C e 4 °C?", "o": ["O volume diminui com o aquecimento, e a água tem a maior densidade a 4 °C.", "O volume aumenta sempre.", "A água não muda de volume.", "A água congela a 4 °C."], "a": 0, "h": "É por isso que lagos congelam de cima para baixo.", "e": "Entre 0 °C e 4 °C a água se contrai ao ser aquecida. A 4 °C a densidade é máxima.", "x": {"1": "Entre 0 e 4 °C o volume diminui ao aquecer. Essa é a anomalia.", "2": "A água muda de volume, só que de forma anômala.", "3": "A água congela a 0 °C ao nível do mar, não a 4 °C."}, "an": "agua_vol", "n": 2}, {"id": "t021", "t": "dl", "q": "Por que o gelo se forma primeiro na superfície de lagos de países frios, preservando a vida embaixo?", "o": ["Porque a água a 4 °C é a mais densa e fica no fundo, e o gelo é menos denso e flutua.", "Porque o fundo é mais frio.", "Porque a água do fundo congela primeiro.", "Porque o gelo é mais denso que a água."], "a": 0, "h": "Relacione densidade e dilatação anômala.", "e": "A água mais fria (perto de 0 °C) e o gelo ficam em cima, e a água a 4 °C, mais densa, fica no fundo.", "x": {"1": "O fundo do lago se mantém mais quente, a cerca de 4 °C.", "2": "A água a 4 °C é a mais densa e fica no fundo, por isso o fundo não congela primeiro.", "3": "Ao contrário: o gelo é menos denso e por isso flutua."}, "an": "lago", "n": 3}, {"id": "t022", "t": "dl", "q": "Verdadeiro ou falso: em um líquido, a dilatação aparente observada em um frasco depende também da dilatação do frasco.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "O frasco também dilata.", "e": "O líquido e o recipiente dilatam. A dilatação aparente do líquido é a real menos a do recipiente.", "v": 1, "x": {"1": "O frasco também dilata, então o que se observa é a dilatação aparente. A afirmação é verdadeira."}, "an": "frasco", "n": 1}, {"id": "t023", "an": "calc_t023", "t": "dl", "q": "Uma barra de 2 m, com α = 1,2 × 10⁻⁵ °C⁻¹, é aquecida em 50 °C. Qual é o aumento de comprimento?", "o": ["1,2 mm", "0,12 mm", "12 mm", "1,2 m"], "a": 0, "h": "ΔL = L₀·α·ΔT.", "e": "ΔL = 2 × 1,2 × 10⁻⁵ × 50 = 1,2 × 10⁻³ m = 1,2 mm.", "c": 1, "x": {"1": "0,12 mm erra a casa decimal. Calcule ΔL = 2 · 1,2 × 10⁻⁵ · 50.", "2": "12 mm é dez vezes maior que o resultado correto.", "3": "1,2 m seria uma dilatação enorme. A conta dá 1,2 × 10⁻³ m = 1,2 mm."}, "n": 2}, {"id": "t024", "an": "calc_t024", "t": "dl", "q": "Uma placa tem área de 1 m² a 20 °C. Sabendo que β = 2,4 × 10⁻⁵ °C⁻¹, qual é a variação de área ao ser aquecida a 120 °C?", "o": ["2,4 × 10⁻³ m²", "2,4 × 10⁻⁵ m²", "2,4 m²", "1,2 × 10⁻³ m²"], "a": 0, "h": "ΔA = A₀·β·ΔT.", "e": "ΔA = 1 × 2,4 × 10⁻⁵ × 100 = 2,4 × 10⁻³ m².", "c": 1, "x": {"1": "Faltou considerar ΔT = 100 °C: ΔA = 1 · 2,4 × 10⁻⁵ · 100.", "2": "2,4 m² é mil vezes maior que o certo.", "3": "1,2 × 10⁻³ aparece ao usar α no lugar de β. Aqui o dado é β."}, "n": 3}, {"id": "t025", "an": "caloria", "t": "cl", "q": "A caloria (cal) é uma unidade de:", "o": ["Energia (calor).", "Temperatura.", "Massa.", "Potência."], "a": 0, "h": "1 cal ≈ 4,2 J.", "e": "A caloria mede energia. No SI, a unidade de energia é o joule: 1 cal ≈ 4,2 J.", "x": {"1": "Temperatura mede-se em °C, K ou °F.", "2": "Massa tem outras unidades, como o grama.", "3": "Potência é energia por tempo, em watts ou cal/s."}, "n": 1}, {"id": "t026", "an": "cal_esp", "t": "cl", "q": "O calor específico de uma substância indica:", "o": ["A quantidade de calor necessária para variar em 1 °C a temperatura de 1 g da substância.", "A temperatura em que ela derrete.", "A massa de 1 cm³ da substância.", "A rapidez com que ela esfria sempre."], "a": 0, "h": "É o valor de c em Q = m·c·ΔT.", "e": "O calor específico (c) é a quantidade de calor por unidade de massa para variar 1 °C a temperatura.", "x": {"1": "O calor específico não indica a temperatura de fusão.", "2": "Isso seria a densidade.", "3": "Ele indica a quantidade de calor por grama por °C, não uma rapidez."}, "n": 1}, {"id": "t027", "an": "cal_esp", "t": "cl", "q": "Qual é a expressão do calor sensível?", "o": ["Q = m · c · ΔT", "Q = m · L", "Q = m / (c · ΔT)", "Q = c / (m · ΔT)"], "a": 0, "h": "Calor que muda a temperatura, sem mudar de estado.", "e": "O calor sensível é Q = m·c·ΔT. O calor latente (mudança de estado) é Q = m·L.", "x": {"1": "Essa é a fórmula do calor latente.", "2": "A massa multiplica, não divide, porque mais massa exige mais calor.", "3": "c aparece multiplicando, e não dividindo."}, "n": 1}, {"id": "t028", "an": "cal_esp", "t": "cl", "q": "Qual é o calor específico aproximado da água líquida?", "o": ["1 cal/g·°C", "0,1 cal/g·°C", "10 cal/g·°C", "80 cal/g·°C"], "a": 0, "h": "É o valor usado como referência.", "e": "A água tem calor específico de cerca de 1 cal/(g·°C), um valor alto em relação a outras substâncias.", "x": {"1": "0,1 cal/g·°C é bem menor que o da água.", "2": "10 cal/g·°C é alto demais para a água.", "3": "80 cal/g é o calor latente de fusão do gelo."}, "n": 1}, {"id": "t029", "an": "cal_esp", "t": "cl", "q": "Por que, na praia, a areia esquenta mais depressa que a água do mar?", "o": ["Porque a areia tem calor específico menor que o da água.", "Porque a água não recebe sol.", "Porque a areia é mais densa que o mar.", "Porque a água tem calor específico menor."], "a": 0, "h": "Compare c da areia e da água.", "e": "Com a mesma energia, a substância de menor calor específico varia mais a temperatura.", "x": {"1": "A água também recebe sol; ela esquenta menos.", "2": "A densidade não explica o aquecimento mais rápido.", "3": "Está invertido: a água tem calor específico maior, então esquenta mais devagar."}, "n": 2}, {"id": "t030", "an": "cap_term", "t": "cl", "q": "O que é capacidade térmica de um corpo?", "o": ["A quantidade de calor necessária para variar em 1 °C a temperatura do corpo todo.", "A quantidade de água que ele contém.", "A temperatura máxima que ele suporta.", "A massa dividida pelo volume."], "a": 0, "h": "C = Q / ΔT = m·c.", "e": "A capacidade térmica é C = m·c, o calor necessário para variar a temperatura do corpo em 1 °C.", "x": {"1": "A capacidade térmica não mede quantidade de água.", "2": "Não é uma temperatura-limite do corpo.", "3": "Massa dividida por volume é a densidade."}, "n": 2}, {"id": "t031", "an": "cal_esp", "t": "cl", "q": "Dois corpos de materiais diferentes recebem a mesma quantidade de calor e têm a mesma massa. Qual esquenta mais?", "o": ["O de menor calor específico.", "O de maior calor específico.", "Os dois esquentam igual.", "O mais claro."], "a": 0, "h": "Isole a variação de temperatura: ΔT = Q / (m·c).", "e": "Da equação Q = m·c·ΔT, tiramos ΔT = Q / (m·c).\nComo Q e m são iguais nos dois corpos, ΔT depende só de c, em proporção inversa: quanto menor o calor específico, maior o aquecimento.\nExemplo com Q = 1 000 cal e m = 100 g:\nSe c = 0,1 cal/g·°C: ΔT = 1 000 / (100 · 0,1) = 100 °C.\nSe c = 1 cal/g·°C: ΔT = 1 000 / (100 · 1) = 10 °C.", "x": {"1": "Com c maior, o denominador m·c cresce e ΔT diminui: a mesma quantidade de calor aquece menos.", "2": "Só seriam iguais se os dois tivessem o mesmo c. Como os materiais são diferentes, os c também são.", "3": "A cor não entra na equação Q = m·c·ΔT; ela só afeta a absorção de radiação."}, "n": 3}, {"id": "t032", "t": "cl", "q": "Em um sistema isolado, dois corpos trocam calor até o equilíbrio. Vale que:", "o": ["A soma dos calores trocados é zero (o que um perde, o outro ganha).", "O calor desaparece.", "Os dois ficam com a mesma massa.", "Os dois ficam com a mesma capacidade térmica."], "a": 0, "h": "Conservação de energia.", "e": "Em um sistema isolado, ΣQ = 0: o calor cedido por um é igual ao absorvido pelo outro.", "x": {"1": "O calor não desaparece: ele é conservado na troca.", "2": "As massas não precisam ficar iguais.", "3": "As capacidades térmicas não se igualam. As temperaturas é que se igualam."}, "an": "equil_termico", "n": 2}, {"id": "t033", "an": "caloria", "t": "cl", "q": "Verdadeiro ou falso: 1 cal equivale, aproximadamente, a 4,2 J.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "É o equivalente mecânico do calor.", "e": "Uma caloria corresponde a cerca de 4,2 joules.", "v": 1, "x": {"1": "1 cal ≈ 4,2 J. A afirmação é verdadeira."}, "n": 1}, {"id": "t034", "an": "calc_t034", "t": "cl", "q": "Qual é a quantidade de calor necessária para aquecer 200 g de água de 20 °C a 50 °C? (c = 1 cal/g·°C)", "o": ["6000 cal", "600 cal", "4000 cal", "10 000 cal"], "a": 0, "h": "Q = m·c·ΔT.", "e": "Q = 200 × 1 × (50 − 20) = 6000 cal.", "c": 1, "x": {"1": "600 cal vem de um erro de dez vezes na conta.", "2": "4000 cal seria ΔT = 20 °C. Aqui ΔT = 30 °C.", "3": "10 000 cal não aparece da fórmula Q = 200 · 1 · 30."}, "n": 2}, {"id": "t035", "an": "calc_t035", "t": "cl", "q": "Um corpo de capacidade térmica 50 cal/°C recebe 1000 cal. Qual é a variação de temperatura?", "o": ["20 °C", "50 °C", "0,05 °C", "2 °C"], "a": 0, "h": "ΔT = Q / C.", "e": "ΔT = 1000 / 50 = 20 °C.", "c": 1, "x": {"1": "50 é a capacidade térmica, não a variação de temperatura.", "2": "Foi feito C / Q em vez de Q / C.", "3": "2 °C erra a ordem de grandeza: ΔT = 1000/50."}, "n": 2}, {"id": "t036", "t": "cl", "q": "Misturam-se 100 g de água a 80 °C com 100 g de água a 20 °C, em um recipiente isolado. Qual é a temperatura final?", "o": ["50 °C", "60 °C", "40 °C", "100 °C"], "a": 0, "h": "Massas iguais e mesmo c: o calor cedido é igual ao recebido.", "e": "Q cedido + Q recebido = 0\n100·1·(T − 80) + 100·1·(T − 20) = 0\n100·T − 8 000 + 100·T − 2 000 = 0\n200·T = 10 000\nT = 10 000 / 200 = 50 °C", "c": 1, "x": {"1": "60 °C ficaria mais perto da água quente do que da fria, mas as massas são iguais.", "2": "40 °C ficaria mais perto da água fria, mas as massas são iguais.", "3": "100 °C é maior que as duas temperaturas iniciais."}, "an": "equil_termico", "n": 2}, {"id": "t037", "an": "estados", "t": "me", "q": "Qual é o nome da passagem de sólido para líquido?", "o": ["Fusão.", "Solidificação.", "Vaporização.", "Condensação."], "a": 0, "h": "É o que acontece com o gelo no calor.", "e": "Sólido para líquido é fusão. Líquido para sólido é solidificação.", "x": {"1": "Solidificação é o caminho inverso, de líquido para sólido.", "2": "Vaporização é de líquido para gás.", "3": "Condensação é de gás para líquido."}, "n": 1}, {"id": "t038", "an": "estados", "t": "me", "q": "Qual é o nome da passagem de líquido para gás?", "o": ["Vaporização.", "Fusão.", "Sublimação.", "Solidificação."], "a": 0, "h": "Inclui a evaporação e a ebulição.", "e": "Líquido para gás é vaporização. Gás para líquido é condensação.", "x": {"1": "Fusão é de sólido para líquido.", "2": "Sublimação é a passagem direta de sólido para gás.", "3": "Solidificação é de líquido para sólido."}, "n": 1}, {"id": "t039", "t": "me", "q": "Durante a fusão do gelo, a 0 °C, enquanto ainda há gelo e água, a temperatura:", "o": ["Permanece constante, embora o gelo receba calor.", "Aumenta continuamente.", "Diminui.", "Oscila sem regra."], "a": 0, "h": "Pense no patamar do gráfico de aquecimento.", "e": "Durante a mudança de estado de uma substância pura, a temperatura fica constante. O calor é usado para mudar o estado.", "f": "curva", "x": {"1": "Durante a mudança de estado a temperatura fica constante.", "2": "Ela também não diminui. O calor é usado para mudar de estado.", "3": "Fica constante e bem definida em 0 °C."}, "an": "aquec", "n": 2}, {"id": "t040", "an": "aquec", "t": "me", "q": "O calor latente é:", "o": ["A quantidade de calor por unidade de massa necessária para mudar o estado, sem variar a temperatura.", "A quantidade de calor que muda a temperatura de 1 g em 1 °C.", "A temperatura em que ocorre a ebulição.", "A energia guardada no corpo."], "a": 0, "h": "Q = m·L.", "e": "O calor latente L é o calor por unidade de massa que provoca a mudança de estado a temperatura constante.", "x": {"1": "Isso descreve o calor específico.", "2": "A temperatura de ebulição é outra coisa.", "3": "O calor latente não é energia guardada: é o calor trocado na mudança de estado."}, "n": 1}, {"id": "t041", "an": "aquec", "t": "me", "q": "Qual é o calor latente de fusão do gelo, aproximadamente?", "o": ["80 cal/g", "540 cal/g", "1 cal/g", "0,5 cal/g"], "a": 0, "h": "Valor usado nos exercícios de gelo.", "e": "O calor latente de fusão do gelo é de cerca de 80 cal/g. O de vaporização da água é de cerca de 540 cal/g.", "x": {"1": "540 cal/g é o calor latente de vaporização da água.", "2": "1 cal/g·°C é o calor específico da água.", "3": "0,5 cal/g·°C aproxima o calor específico do gelo."}, "n": 1}, {"id": "t042", "an": "evap_ebul", "t": "me", "q": "Qual é a diferença entre evaporação e ebulição?", "o": ["A evaporação ocorre na superfície, em qualquer temperatura; a ebulição ocorre em toda a massa, em temperatura definida.", "São o mesmo fenômeno.", "A ebulição ocorre só em sólidos.", "A evaporação ocorre só em 100 °C."], "a": 0, "h": "Pense em roupa secando no varal e água na panela.", "e": "A evaporação é lenta e superficial. A ebulição é rápida, em todo o líquido, a uma temperatura que depende da pressão.", "x": {"1": "São fenômenos diferentes, e ocorrem de modos diferentes.", "2": "A ebulição ocorre em líquidos.", "3": "A evaporação acontece em várias temperaturas."}, "n": 2}, {"id": "t043", "an": "pressao_ebul", "t": "me", "q": "Por que a água ferve a uma temperatura menor em locais de grande altitude?", "o": ["Porque a pressão atmosférica é menor.", "Porque a gravidade é maior.", "Porque a água é mais pura.", "Porque o ar é mais quente."], "a": 0, "h": "Pressão menor, ebulição mais fácil.", "e": "Com pressão menor, as moléculas escapam mais facilmente, e o ponto de ebulição diminui.", "x": {"1": "A gravidade não aumenta com a altitude.", "2": "A pureza não explica a diferença.", "3": "O ar mais quente não baixa o ponto de ebulição. O que muda é a pressão."}, "n": 2}, {"id": "t044", "an": "estados", "t": "me", "q": "Verdadeiro ou falso: a sublimação é a passagem direta do estado sólido para o gasoso, como a naftalina.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Sem passar pelo líquido.", "e": "Na sublimação, o sólido vira gás diretamente. O gelo-seco e a naftalina são exemplos.", "v": 1, "x": {"1": "Sublimação é a passagem direta de sólido para gás, como a da naftalina. A afirmação é verdadeira."}, "n": 1}, {"id": "t045", "t": "me", "q": "No gráfico de aquecimento da água, os trechos horizontais indicam:", "o": ["Mudança de estado, com temperatura constante.", "Aquecimento do gelo.", "Resfriamento da água.", "Erro de medição."], "a": 0, "h": "Quanto calor é usado para mudar o estado?", "e": "Nos patamares, o calor recebido é empregado na mudança de estado (fusão e ebulição) e a temperatura fica constante.", "f": "curva", "x": {"1": "Aquecer o gelo é um trecho inclinado, em que a temperatura sobe.", "2": "Resfriar a água também é um trecho inclinado, e a temperatura cai.", "3": "Os patamares são previstos pela teoria: no patamar há mudança de estado."}, "an": "aquec", "n": 2}, {"id": "t046", "an": "suor", "t": "me", "q": "Por que suar ajuda a resfriar o corpo?", "o": ["Porque a evaporação do suor retira calor da pele.", "Porque o suor aquece o corpo.", "Porque o suor é gelado.", "Porque a pele absorve a água."], "a": 0, "h": "A evaporação consome energia.", "e": "Para evaporar, o suor absorve calor da pele, e o corpo esfria.", "x": {"1": "O suor não aquece o corpo. O efeito de resfriar vem da evaporação.", "2": "O suor sai quase na temperatura da pele. O que resfria é evaporar.", "3": "A absorção de água pela pele não explica o efeito. A evaporação retira calor."}, "n": 1}, {"id": "t047", "an": "calc_t047", "t": "me", "q": "Qual é a quantidade de calor para fundir 50 g de gelo a 0 °C? (L = 80 cal/g)", "o": ["4000 cal", "400 cal", "130 cal", "40 000 cal"], "a": 0, "h": "Q = m·L.", "e": "Q = 50 × 80 = 4000 cal.", "c": 1, "x": {"1": "400 cal erra por um fator de 10: Q = 50 · 80.", "2": "130 cal vem de somar 50 + 80, mas a conta é um produto.", "3": "40 000 cal tem fator 10 a mais."}, "n": 1}, {"id": "t048", "an": "calc_t048", "t": "me", "q": "Quanto calor é necessário para transformar 10 g de água a 100 °C em vapor a 100 °C? (L = 540 cal/g)", "o": ["5400 cal", "540 cal", "54 cal", "54 000 cal"], "a": 0, "h": "Q = m·L.", "e": "Q = 10 × 540 = 5400 cal.", "c": 1, "x": {"1": "540 cal é o calor para 1 g. Aqui são 10 g.", "2": "54 cal dividiu em vez de multiplicar por 10.", "3": "54 000 cal tem fator 10 a mais."}, "n": 1}, {"id": "t049", "an": "tres_formas", "t": "pc", "q": "Quais são as três formas de propagação do calor?", "o": ["Condução, convecção e irradiação.", "Fusão, ebulição e sublimação.", "Dilatação, contração e compressão.", "Reflexão, refração e difração."], "a": 0, "h": "Uma delas acontece até no vácuo.", "e": "O calor se propaga por condução, convecção e irradiação.", "x": {"1": "Essas são mudanças de estado, não formas de propagação.", "2": "Dilatação, contração e compressão são efeitos mecânicos ou térmicos, não formas de transporte de calor.", "3": "Reflexão, refração e difração são fenômenos ondulatórios."}, "n": 1}, {"id": "t050", "t": "pc", "q": "A condução térmica ocorre principalmente:", "o": ["Em sólidos, pela vibração das partículas, sem transporte de matéria.", "Em líquidos, com correntes.", "No vácuo.", "Somente em gases."], "a": 0, "h": "Pense em uma colher de metal em uma panela quente.", "e": "Na condução, a energia passa de partícula a partícula, sem que haja deslocamento do material.", "x": {"1": "Em líquidos a convecção é a forma mais comum.", "2": "No vácuo não há partículas, então não há condução.", "3": "A condução ocorre sobretudo em sólidos; nos gases é muito fraca."}, "an": "conducao", "n": 1}, {"id": "t051", "t": "pc", "q": "A convecção térmica é o transporte de calor:", "o": ["Por movimento de massa do fluido (correntes de convecção).", "Por ondas eletromagnéticas.", "Apenas em sólidos.", "Somente no vácuo."], "a": 0, "h": "O ar quente sobe e o frio desce.", "e": "Em líquidos e gases, as porções quentes (menos densas) sobem e as frias descem, formando correntes.", "x": {"1": "Ondas eletromagnéticas descrevem a irradiação.", "2": "A convecção exige fluido. Em sólidos o transporte é por condução.", "3": "No vácuo não há fluido, então não há convecção."}, "an": "convec", "n": 1}, {"id": "t052", "t": "pc", "q": "A irradiação térmica é a propagação de calor por:", "o": ["Ondas eletromagnéticas, inclusive no vácuo.", "Contato direto entre sólidos.", "Correntes de líquido.", "Dilatação do material."], "a": 0, "h": "É como o calor do Sol chega à Terra.", "e": "A irradiação ocorre por ondas eletromagnéticas e não precisa de meio material.", "x": {"1": "Contato direto entre sólidos é condução.", "2": "Correntes de líquido são convecção.", "3": "A dilatação não propaga calor."}, "an": "sol_terra", "n": 1}, {"id": "t053", "t": "pc", "q": "Como o calor do Sol chega até a Terra?", "o": ["Por irradiação.", "Por condução.", "Por convecção.", "Por dilatação."], "a": 0, "h": "Entre o Sol e a Terra há vácuo.", "e": "No vácuo só é possível a irradiação.", "x": {"1": "Entre o Sol e a Terra há vácuo, onde não há condução.", "2": "Convecção exige um fluido. No espaço quase não há matéria.", "3": "A dilatação não é uma forma de propagação do calor."}, "an": "sol_terra", "n": 1}, {"id": "t054", "t": "pc", "q": "Por que o congelador fica na parte de cima da geladeira?", "o": ["Porque o ar frio desce e forma correntes de convecção que resfriam todo o interior.", "Porque o frio sobe.", "Porque a parte de baixo é mais quente por condução.", "Por razões apenas estéticas."], "a": 0, "h": "Ar frio é mais denso.", "e": "O ar frio, mais denso, desce, e o ar mais quente sobe, formando correntes que resfriam toda a geladeira.", "x": {"1": "O frio não sobe: o ar frio é mais denso e desce.", "2": "A condução não explica a posição. É a convecção que faz o ar circular.", "3": "Há razão física: o ar frio desce e resfria o interior."}, "an": "geladeira", "n": 2}, {"id": "t055", "an": "conducao", "t": "pc", "q": "Por que um cabo de panela costuma ser feito de madeira ou plástico?", "o": ["Porque são isolantes térmicos e conduzem mal o calor.", "Porque são bons condutores.", "Porque derretem fácil.", "Porque são mais caros."], "a": 0, "h": "Pense em segurar a panela sem se queimar.", "e": "Madeira e plástico são maus condutores de calor, e por isso protegem a mão.", "x": {"1": "Bons condutores esquentariam o cabo e queimariam a mão.", "2": "Derreter fácil seria um defeito.", "3": "O preço não explica a escolha. O motivo é o isolamento térmico."}, "n": 2}, {"id": "t056", "t": "pc", "q": "Por que a garrafa térmica mantém o líquido quente por muito tempo?", "o": ["Tem paredes duplas espelhadas com vácuo entre elas, reduzindo condução, convecção e irradiação.", "Porque produz calor.", "Porque o vidro é um excelente condutor.", "Porque a tampa é de metal."], "a": 0, "h": "O vácuo não conduz nem convecta.", "e": "O vácuo entre as paredes impede condução e convecção, e o espelhamento reduz a irradiação.", "x": {"1": "A garrafa térmica não produz calor, apenas reduz as perdas.", "2": "O vidro conduz mal, e o vácuo conduz ainda menos.", "3": "A tampa é um detalhe. A principal proteção é a parede dupla com vácuo."}, "an": "garrafa", "n": 2}, {"id": "t057", "t": "pc", "q": "Verdadeiro ou falso: os metais são, em geral, bons condutores de calor.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Pense em uma colher de metal na sopa quente.", "e": "Os metais têm elétrons livres e conduzem bem o calor e a eletricidade.", "v": 1, "x": {"1": "Os metais têm elétrons livres e conduzem bem o calor. A afirmação é verdadeira."}, "an": "conducao", "n": 1}, {"id": "t058", "an": "ar_isolante", "t": "pc", "q": "Por que, no inverno, usamos roupas de lã, que prendem ar entre as fibras?", "o": ["O ar parado é um isolante térmico e reduz a perda de calor do corpo.", "A lã produz calor.", "O ar conduz bem o calor.", "A lã é um ótimo condutor."], "a": 0, "h": "O ar é mau condutor.", "e": "O ar retido nas fibras é um mau condutor, e isso reduz a perda de calor.", "x": {"1": "A lã não produz calor. Quem aquece é o corpo.", "2": "O ar parado conduz mal o calor, por isso isola.", "3": "A lã é isolante, não condutora."}, "n": 2}, {"id": "t059", "an": "cores_sol", "t": "pc", "q": "Por que objetos escuros esquentam mais ao sol do que os claros?", "o": ["Porque absorvem mais radiação e refletem menos.", "Porque refletem mais radiação.", "Porque são mais densos.", "Porque têm calor específico menor sempre."], "a": 0, "h": "Pense numa camiseta preta.", "e": "Superfícies escuras absorvem mais a radiação incidente, e as claras refletem mais.", "x": {"1": "Está invertido: objetos escuros refletem menos.", "2": "A densidade não é o fator principal.", "3": "O calor específico não é o que explica a diferença de cor."}, "n": 2}, {"id": "t060", "an": "tato", "t": "pc", "q": "Em uma noite fria, uma pessoa encosta a mão em um piso de cerâmica e em um tapete, ambos à mesma temperatura. A cerâmica parece mais fria porque:", "o": ["Conduz melhor o calor e retira calor da mão mais depressa.", "Está de fato mais fria que o tapete.", "O tapete produz calor.", "A cerâmica irradia mais."], "a": 0, "h": "Sensação não é temperatura.", "e": "Os dois estão à mesma temperatura, mas a cerâmica conduz melhor e retira calor mais rápido da mão.", "x": {"1": "Ambos estão à mesma temperatura. A sensação é que difere.", "2": "O tapete não produz calor. Ele conduz mal e retira pouco calor da mão.", "3": "A irradiação não explica essa sensação de contato."}, "n": 3}, {"id": "t061", "an": "calc_t061", "t": "tm", "q": "Qual é o valor de 50 °C na escala Kelvin?", "o": ["223 K", "323 K", "50 K", "373 K"], "a": 1, "h": "Some 273.", "e": "TK = TC + 273 = 50 + 273 = 323 K.", "x": {"0": "223 K resultaria de subtrair 50 de 273.", "2": "50 K é o valor em Celsius, sem converter.", "3": "373 K corresponde a 100 °C."}, "n": 1}, {"id": "t062", "an": "calc_t062", "t": "tm", "q": "Um termômetro Fahrenheit marca 68 °F. Qual é a temperatura em °C?", "o": ["36 °C", "20 °C", "40 °C", "154 °C"], "a": 1, "h": "Use TC/5 = (TF − 32)/9.", "e": "TC/5 = (68 − 32)/9 = 4, logo TC = 20 °C.", "x": {"0": "36 não sai de (68 − 32)/1,8. Esse cálculo dá 20.", "2": "40 não vem da fórmula de conversão.", "3": "154 °C resulta de aplicar a conversão inversa (°C para °F)."}, "n": 2}, {"id": "t063", "an": "escalas", "t": "tm", "q": "Uma variação de temperatura de 30 °C corresponde, na escala Kelvin, a uma variação de:", "o": ["303 K", "243 K", "30 K", "86 K"], "a": 2, "h": "As escalas Celsius e Kelvin têm o mesmo tamanho de grau.", "e": "Como TK = TC + 273, ΔTK = ΔTC. A variação de 30 °C é uma variação de 30 K.", "x": {"0": "Somou 273 a uma variação. Isso só vale para valores, não para variações.", "1": "Subtrair 273 de uma variação também é erro.", "3": "86 seria a conversão de 30 °C para °F."}, "n": 1}, {"id": "t064", "an": "escalas", "t": "tm", "q": "A temperatura de 0 °C equivale, na escala Kelvin, a aproximadamente:", "o": ["273 K", "0 K", "100 K", "373 K"], "a": 0, "h": "TK = TC + 273.", "e": "TK = 0 + 273 = 273 K.", "x": {"1": "0 K é o zero absoluto, que corresponde a −273 °C.", "2": "100 K não sai da conversão: soma-se 273, não 100.", "3": "373 K é a ebulição da água (100 °C)."}, "n": 1}, {"id": "t065", "an": "menos40", "t": "tm", "q": "Em que temperatura as escalas Celsius e Fahrenheit marcam o mesmo valor numérico?", "o": ["0", "−40", "32", "100"], "a": 1, "h": "Faça TC = TF em TC/5 = (TF − 32)/9.", "e": "Com TC = TF: 9·TC = 5·TC − 160, então TC = −40. Logo −40 °C = −40 °F.", "x": {"0": "Em 0 °C, a escala Fahrenheit marca 32 °F.", "2": "32 °F corresponde a 0 °C.", "3": "100 °C corresponde a 212 °F."}, "n": 1}, {"id": "t066", "an": "calc_t066", "t": "dl", "q": "Uma barra de 2,0 m, com α = 1,2 × 10⁻⁵ °C⁻¹, é aquecida de 20 °C a 120 °C. Qual é a dilatação da barra?", "o": ["0,24 mm", "2,4 mm", "24 mm", "1,2 mm"], "a": 1, "h": "ΔL = L₀ · α · ΔT.", "e": "ΔL = 2,0 · 1,2 × 10⁻⁵ · 100 = 2,4 × 10⁻³ m = 2,4 mm.", "x": {"0": "0,24 mm erra a casa decimal.", "2": "24 mm é dez vezes maior.", "3": "1,2 mm seria ΔT = 50 °C, mas aqui ΔT = 100 °C."}, "n": 3}, {"id": "t067", "an": "dil_coef", "t": "dl", "q": "Para um mesmo material, qual é a relação entre os coeficientes de dilatação linear (α), superficial (β) e volumétrica (γ)?", "o": ["β = 2α e γ = 3α", "β = α e γ = α", "β = 3α e γ = 2α", "β = α/2 e γ = α/3"], "a": 0, "h": "Pense em quantas dimensões dilatam.", "e": "Aproximadamente, β = 2α (duas dimensões) e γ = 3α (três dimensões).", "x": {"1": "Se β = α e γ = α, não haveria dilatação em área ou volume.", "2": "Os valores estão trocados.", "3": "As frações estão invertidas: os coeficientes crescem com a dimensão."}, "n": 2}, {"id": "t068", "t": "dl", "q": "Por que se deixam pequenas folgas entre os trilhos de uma ferrovia?", "o": ["Para o trilho poder dilatar nos dias quentes sem entortar.", "Para o trem fazer menos barulho apenas.", "Para o trilho contrair no calor.", "Para a água da chuva escoar."], "a": 0, "h": "Pense no que o calor faz com o metal.", "e": "Com o calor, o metal dilata. Sem folga, os trilhos se empurrariam e poderiam deformar.", "x": {"1": "A folga não serve para reduzir barulho.", "2": "No calor o trilho dilata, não contrai.", "3": "A chuva não é o motivo. O motivo é a dilatação."}, "an": "trilhos", "n": 1}, {"id": "t069", "t": "dl", "q": "Uma placa metálica com um furo circular é aquecida. O que acontece com o furo?", "o": ["Aumenta, como se fosse feito do mesmo material da placa.", "Diminui, porque o metal ocupa o espaço.", "Não muda.", "Fecha completamente."], "a": 0, "h": "O furo se comporta como se fosse feito do material.", "e": "A dilatação ocorre em todas as direções. O furo aumenta como se fosse um disco do mesmo material.", "x": {"1": "O furo dilata junto com a placa, não é preenchido pelo metal.", "2": "Ele muda de tamanho como se fosse do material.", "3": "O furo apenas aumenta e não se fecha."}, "an": "furo", "n": 2}, {"id": "t070", "t": "dl", "q": "Um frasco de vidro totalmente cheio de líquido é aquecido e o líquido transborda. Isso ocorre porque, em geral:", "o": ["O líquido dilata mais que o frasco.", "O frasco dilata mais que o líquido.", "O líquido contrai com o calor.", "O vidro não dilata nunca."], "a": 0, "h": "Compare o γ do líquido com o do vidro.", "e": "Em geral, os líquidos dilatam bem mais que o vidro. O excesso de volume transborda (dilatação aparente).", "x": {"1": "Em geral o líquido dilata mais, e não o frasco.", "2": "O líquido dilata com o calor, não contrai.", "3": "O vidro dilata, só que menos que o líquido."}, "an": "frasco", "n": 2}, {"id": "t071", "an": "calc_t071", "t": "cl", "q": "Qual é a quantidade de calor para aquecer 200 g de água de 20 °C a 50 °C? (c = 1 cal/g·°C)", "o": ["4 000 cal", "6 000 cal", "200 cal", "10 000 cal"], "a": 1, "h": "Q = m · c · ΔT.", "e": "Q = 200 · 1 · (50 − 20) = 6 000 cal.", "x": {"0": "4 000 cal seria ΔT = 20 °C. Aqui são 30 °C.", "2": "200 cal ignora a variação de temperatura.", "3": "10 000 cal não vem de Q = 200 · 1 · 30."}, "n": 2}, {"id": "t072", "an": "calc_t072", "t": "cl", "q": "Um corpo de 500 g tem calor específico 0,2 cal/g·°C. Qual é a capacidade térmica?", "o": ["100 cal/°C", "2 500 cal/°C", "0,1 cal/°C", "10 cal/°C"], "a": 0, "h": "C = m · c.", "e": "C = 500 · 0,2 = 100 cal/°C.", "x": {"1": "2 500 cal/°C resulta de dividir 500 por 0,2.", "2": "0,1 cal/°C está longe: C = m · c = 500 · 0,2.", "3": "10 cal/°C erra a conta: 500 × 0,2 = 100."}, "n": 1}, {"id": "t073", "t": "cl", "q": "Misturam-se 500 g de água a 80 °C com 1 500 g de água a 20 °C, em um recipiente isolado. Qual é a temperatura final?", "o": ["50 °C", "40 °C", "35 °C", "30 °C"], "a": 2, "h": "Massas diferentes: a média é ponderada pelas massas, e a água fria é a maior parte.", "e": "Q cedido + Q recebido = 0\n500·1·(T − 80) + 1 500·1·(T − 20) = 0\n500·T − 40 000 + 1 500·T − 30 000 = 0\n2 000·T = 70 000\nT = 70 000 / 2 000 = 35 °C", "c": 1, "n": 3, "x": {"0": "50 °C é a média simples de 80 e 20, mas as massas são diferentes.", "1": "40 °C está acima do equilíbrio: a água fria tem o triplo da massa e puxa a temperatura para perto de 20 °C.", "3": "30 °C está abaixo do equilíbrio: a água quente cede calor suficiente para chegar a 35 °C."}, "an": "calc_t098"}, {"id": "t074", "t": "cl", "q": "Dois corpos em contato térmico, isolados do ambiente, trocam calor até que:", "o": ["Tenham a mesma temperatura.", "Tenham a mesma massa.", "Tenham o mesmo calor específico.", "Um deles chegue a 0 °C."], "a": 0, "h": "Isso é o equilíbrio térmico.", "e": "O calor flui do mais quente para o mais frio até igualar as temperaturas (equilíbrio térmico).", "x": {"1": "As massas não precisam ser iguais.", "2": "Calor específico é propriedade do material.", "3": "O equilíbrio ocorre na temperatura de equilíbrio, que não é 0 °C."}, "an": "equil_termico", "n": 2}, {"id": "t075", "an": "cal_esp", "t": "cl", "q": "Por que, num dia quente, a areia da praia esquenta bem mais que a água do mar?", "o": ["A areia tem calor específico menor que o da água.", "A areia tem calor específico maior que o da água.", "A água não recebe calor do Sol.", "A água tem menos massa."], "a": 0, "h": "Quanto menor o c, maior a variação de temperatura para o mesmo calor.", "e": "A água tem calor específico alto (1 cal/g·°C) e esquenta pouco. A areia tem c bem menor e esquenta mais.", "x": {"1": "Está invertido: a areia tem c menor.", "2": "A água também recebe calor do Sol. Ela esquenta menos.", "3": "A massa não explica por que a areia esquenta mais."}, "n": 2}, {"id": "t076", "an": "calc_t076", "t": "me", "q": "Qual é a quantidade de calor para fundir 100 g de gelo a 0 °C? (L = 80 cal/g)", "o": ["800 cal", "8 000 cal", "180 cal", "80 000 cal"], "a": 1, "h": "Q = m · L.", "e": "Q = 100 · 80 = 8 000 cal, sem mudar a temperatura.", "x": {"0": "800 cal erra por um fator de 10.", "2": "180 cal vem de somar 100 + 80.", "3": "80 000 cal tem fator 10 a mais."}, "n": 1}, {"id": "t077", "t": "me", "q": "Durante a ebulição da água, a pressão constante, a temperatura:", "o": ["Aumenta continuamente.", "Diminui.", "Permanece constante.", "Oscila sem regra."], "a": 2, "h": "Todo o calor vai para mudar de estado.", "e": "Durante a mudança de estado de uma substância pura, a pressão constante, a temperatura fica constante.", "x": {"0": "Durante a mudança de estado a temperatura se mantém.", "1": "A temperatura não diminui na ebulição.", "3": "A temperatura não oscila: fica constante."}, "an": "aquec", "n": 1}, {"id": "t078", "an": "estados", "t": "me", "q": "Como se chama a passagem direta do estado sólido para o gasoso?", "o": ["Fusão", "Sublimação", "Condensação", "Solidificação"], "a": 1, "h": "Exemplo: naftalina.", "e": "Sublimação é a passagem direta de sólido para gás, sem passar pelo líquido.", "x": {"0": "Fusão é de sólido para líquido.", "2": "Condensação é de gás para líquido.", "3": "Solidificação é de líquido para sólido."}, "n": 1}, {"id": "t079", "an": "pressao_ebul", "t": "me", "q": "Por que a panela de pressão cozinha mais rápido?", "o": ["A pressão maior eleva o ponto de ebulição da água.", "A pressão maior abaixa o ponto de ebulição.", "Ela produz calor por si mesma.", "Ela retira o ar da água."], "a": 0, "h": "A temperatura de ebulição depende da pressão.", "e": "Com pressão maior, a água ferve acima de 100 °C. Os alimentos cozinham em temperatura mais alta e mais depressa.", "x": {"1": "Pressão maior eleva, e não abaixa, o ponto de ebulição.", "2": "A panela não produz calor: só o fogo aquece.", "3": "Ela não retira o ar da água. Mantém o vapor preso, aumentando a pressão."}, "n": 2}, {"id": "t080", "an": "calc_t080", "t": "me", "q": "Qual é o calor para vaporizar 10 g de água a 100 °C? (L = 540 cal/g)", "o": ["54 cal", "540 cal", "5 400 cal", "54 000 cal"], "a": 2, "h": "Q = m · L.", "e": "Q = 10 · 540 = 5 400 cal.", "x": {"0": "54 cal dividiu 540 por 10.", "1": "540 cal é o calor para 1 g.", "3": "54 000 cal tem fator 10 a mais."}, "n": 1}, {"id": "t081", "t": "pc", "q": "Como o calor do Sol chega à Terra?", "o": ["Por radiação, que se propaga também no vácuo.", "Por condução pelo ar.", "Por convecção pelo espaço.", "Por condução pelo vácuo."], "a": 0, "h": "Entre o Sol e a Terra quase não há matéria.", "e": "A radiação (ondas eletromagnéticas) não precisa de meio material e atravessa o vácuo.", "x": {"1": "No espaço quase não há ar. Não pode haver condução pelo ar.", "2": "A convecção exige fluido. No espaço não há.", "3": "No vácuo não há matéria para conduzir."}, "an": "sol_terra", "n": 1}, {"id": "t082", "t": "pc", "q": "A convecção térmica ocorre:", "o": ["Em fluidos, por correntes de matéria de densidades diferentes.", "Somente em sólidos.", "Somente no vácuo.", "Em metais, por vibração dos átomos."], "a": 0, "h": "O fluido quente sobe e o frio desce.", "e": "Na convecção, o fluido aquecido fica menos denso e sobe, e o frio desce. Só ocorre em líquidos e gases.", "x": {"1": "Nos sólidos o transporte é por condução.", "2": "No vácuo não há fluido.", "3": "A vibração dos átomos em metais é condução."}, "an": "convec", "n": 1}, {"id": "t083", "t": "pc", "q": "A parede dupla com vácuo da garrafa térmica reduz principalmente as trocas por:", "o": ["Condução e convecção.", "Radiação apenas.", "Dilatação.", "Sublimação."], "a": 0, "h": "No vácuo não há matéria para conduzir nem correntes.", "e": "Sem matéria entre as paredes, não há condução nem convecção. O espelhamento reduz a radiação.", "x": {"1": "A radiação é reduzida pelo espelhamento, não pelo vácuo.", "2": "A dilatação não é uma troca de calor.", "3": "Sublimação é mudança de estado."}, "an": "garrafa", "n": 2}, {"id": "t084", "an": "conducao", "t": "pc", "q": "Por que o cabo de uma panela costuma ser de madeira ou plástico?", "o": ["São maus condutores de calor.", "São bons condutores de calor.", "Dilatam menos que o metal.", "Têm calor latente maior."], "a": 0, "h": "Você não quer se queimar.", "e": "Madeira e plástico são isolantes térmicos e conduzem mal o calor, protegendo a mão.", "x": {"1": "Bons condutores esquentariam o cabo.", "2": "A dilatação não é o motivo da escolha.", "3": "Calor latente não tem a ver com o cabo."}, "n": 1}, {"id": "t085", "t": "pc", "q": "Na condução, o fluxo de calor é Φ = k · A · ΔT / L. Se a espessura L dobra, mantidos os demais valores, o fluxo:", "o": ["Dobra.", "Fica pela metade.", "Não muda.", "Quadruplica."], "a": 1, "h": "Φ é inversamente proporcional a L.", "e": "Como Φ ∝ 1/L, dobrar L reduz o fluxo à metade.", "x": {"0": "Dobra se o fluxo fosse proporcional a L, mas é inversamente proporcional.", "2": "O fluxo muda com L: Φ ∝ 1/L.", "3": "Quadruplicaria se fosse 1/L² ou 4L. Aqui é 1/L."}, "an": "conducao", "n": 3}, {"id": "t086", "t": "me", "q": "Quanto calor é necessário para transformar 200 g de gelo a −10 °C em água a 20 °C? (c do gelo = 0,5 cal/g·°C; c da água = 1 cal/g·°C; L de fusão = 80 cal/g)", "o": ["21 000 cal", "20 000 cal", "17 000 cal", "5 000 cal"], "a": 0, "h": "Some três etapas: aquecer o gelo, fundir e aquecer a água.", "e": "Gelo: 200·0,5·10 = 1 000 cal. Fusão: 200·80 = 16 000 cal. Água: 200·1·20 = 4 000 cal. Total: 21 000 cal.", "c": 1, "n": 3, "x": {"1": "20 000 cal esquece o aquecimento do gelo de −10 °C até 0 °C.", "2": "17 000 cal esquece o aquecimento da água de 0 °C até 20 °C.", "3": "5 000 cal esquece a fusão do gelo, que é a etapa que mais consome calor."}, "an": "calc_t086"}, {"id": "t087", "t": "cl", "q": "Misturam-se 200 g de água a 90 °C com 300 g de água a 20 °C, em um recipiente isolado. Qual é a temperatura final?", "o": ["55 °C", "48 °C", "60 °C", "42 °C"], "a": 1, "h": "Q cedido + Q recebido = 0: use as massas como pesos.", "e": "200·(Tf − 90) + 300·(Tf − 20) = 0 → 500·Tf = 24 000 → Tf = 48 °C.", "c": 1, "n": 3, "x": {"0": "55 °C é a média simples das temperaturas; as massas são diferentes.", "2": "60 °C está acima do ponto de equilíbrio: a massa maior é a fria.", "3": "42 °C está abaixo do correto: a água quente cede calor suficiente para chegar a 48 °C."}, "an": "calc_t087"}, {"id": "t088", "t": "cl", "q": "Um bloco metálico de 100 g a 200 °C é colocado em 200 g de água a 20 °C. O equilíbrio ocorre a 30 °C. Qual é, aproximadamente, o calor específico do metal? (c da água = 1 cal/g·°C)", "o": ["0,20 cal/g·°C", "0,06 cal/g·°C", "0,12 cal/g·°C", "1,0 cal/g·°C"], "a": 2, "h": "O calor perdido pelo metal é igual ao ganho pela água.", "e": "Água: 200·1·(30 − 20) = 2 000 cal. Metal: 100·c·(200 − 30) = 17 000·c. Logo c = 2 000/17 000 ≈ 0,12 cal/g·°C.", "c": 1, "n": 3, "x": {"0": "0,20 cal/g·°C usa a variação de temperatura errada do metal (100 °C em vez de 170 °C).", "1": "0,06 cal/g·°C é metade do valor correto.", "3": "1,0 cal/g·°C é o calor específico da água, não do metal."}, "an": "calc_t088"}, {"id": "t089", "t": "dl", "q": "Uma barra de 5 m, com α = 1,2 × 10⁻⁵ °C⁻¹, é aquecida de 20 °C a 120 °C. Qual é o aumento de comprimento?", "o": ["0,6 mm", "60 mm", "3 mm", "6 mm"], "a": 3, "h": "ΔL = L₀·α·ΔT, com ΔT = 120 − 20.", "e": "ΔL = 5 · 1,2×10⁻⁵ · 100 = 6×10⁻³ m = 6 mm.", "c": 1, "n": 2, "x": {"0": "0,6 mm está dez vezes menor: confira as potências de dez.", "1": "60 mm está dez vezes maior: confira as potências de dez.", "2": "3 mm é metade do correto: usou ΔT = 50 °C."}, "an": "calc_t089"}, {"id": "t090", "t": "dl", "q": "Uma chapa de área 2 m², com α = 2 × 10⁻⁵ °C⁻¹, é aquecida em 50 °C. Qual é o aumento de área?", "o": ["40 cm²", "20 cm²", "4 cm²", "80 cm²"], "a": 0, "h": "Dilatação superficial: ΔA = A₀·β·ΔT, com β = 2α.", "e": "β = 2·2×10⁻⁵ = 4×10⁻⁵ °C⁻¹. ΔA = 2 · 4×10⁻⁵ · 50 = 4×10⁻³ m² = 40 cm².", "c": 1, "n": 3, "x": {"1": "20 cm² usa α no lugar de β = 2α na dilatação superficial.", "2": "4 cm² está dez vezes menor: confira a conversão de m² para cm².", "3": "80 cm² usa 4α no lugar de 2α."}, "an": "calc_t090"}, {"id": "t091", "t": "dl", "q": "Um frasco de vidro com 500 cm³ está completamente cheio de um líquido de γ = 1,0 × 10⁻³ °C⁻¹. O frasco tem γ = 0,2 × 10⁻³ °C⁻¹. Aquecendo-se o conjunto em 40 °C, quanto líquido transborda?", "o": ["20 cm³", "16 cm³", "4 cm³", "24 cm³"], "a": 1, "h": "Transborda a dilatação aparente: γ do líquido menos γ do frasco.", "e": "γ aparente = 1,0×10⁻³ − 0,2×10⁻³ = 0,8×10⁻³ °C⁻¹. ΔV = 500 · 0,8×10⁻³ · 40 = 16 cm³.", "c": 1, "n": 3, "x": {"0": "20 cm³ é a dilatação real do líquido; o frasco também dilata e esconde parte dela.", "2": "4 cm³ é a dilatação do frasco, não o que transborda.", "3": "24 cm³ soma as dilatações em vez de subtraí-las."}, "an": "calc_t091"}, {"id": "t092", "t": "tm", "q": "Uma temperatura de 104 °F corresponde, na escala Kelvin, a:", "o": ["377 K", "40 K", "313 K", "233 K"], "a": 2, "h": "Passe de °F para °C e depois de °C para K.", "e": "TC = (104 − 32)·5/9 = 40 °C. TK = 40 + 273 = 313 K.", "c": 1, "n": 2, "x": {"0": "377 K soma 273 direto aos 104 °F, sem converter para Celsius.", "1": "40 K é o valor em Celsius; falta somar 273.", "3": "233 K subtrai 40 de 273 em vez de somar."}, "an": "calc_t092"}, {"id": "t093", "t": "cl", "q": "Um aquecedor de 500 W, com todo o calor aproveitado, aquece 2 kg de água de 20 °C a 70 °C. Quanto tempo leva? (c da água = 4 200 J/kg·°C)", "o": ["7 min", "28 min", "84 min", "14 min"], "a": 3, "h": "Q = m·c·ΔT e P = Q / t.", "e": "Q = 2 · 4 200 · 50 = 420 000 J. t = Q / P = 420 000/500 = 840 s = 14 min.", "c": 1, "n": 3, "x": {"0": "7 min é metade do correto: confira a massa de água.", "1": "28 min é o dobro do correto: confira a variação de temperatura.", "2": "84 min erra a conversão de segundos para minutos."}, "an": "calc_t093"}, {"id": "t094", "t": "me", "q": "Quanto calor é liberado quando 100 g de vapor de água a 100 °C se condensam e a água resultante esfria até 60 °C? (L de vaporização = 540 cal/g; c da água = 1 cal/g·°C)", "o": ["58 000 cal", "54 000 cal", "4 000 cal", "94 000 cal"], "a": 0, "h": "Some a condensação a 100 °C e o resfriamento da água.", "e": "Condensação: 100·540 = 54 000 cal. Resfriamento: 100·1·40 = 4 000 cal. Total: 58 000 cal.", "c": 1, "n": 3, "x": {"1": "54 000 cal esquece o resfriamento da água de 100 °C a 60 °C.", "2": "4 000 cal esquece a condensação, que libera a maior parte do calor.", "3": "94 000 cal usa uma variação de 100 °C em vez de 40 °C no resfriamento."}, "an": "calc_t094"}, {"id": "t095", "t": "cl", "q": "Um corpo de 400 g tem calor específico 0,25 cal/g·°C. Que variação de temperatura ele sofre ao receber 3 000 cal?", "o": ["7,5 °C", "30 °C", "3 °C", "300 °C"], "a": 1, "h": "Capacidade térmica C = m·c; depois ΔT = Q / C.", "e": "C = 400 · 0,25 = 100 cal/°C. ΔT = 3 000/100 = 30 °C.", "c": 1, "n": 2, "x": {"0": "7,5 °C divide só pela massa e esquece o calor específico.", "2": "3 °C está dez vezes menor: confira a capacidade térmica.", "3": "300 °C está dez vezes maior: confira a capacidade térmica."}, "an": "calc_t095"}, {"id": "t096", "t": "pc", "q": "Uma vidraça de área 1,5 m² e espessura 5 mm tem k = 0,8 W/m·°C. A diferença de temperatura entre as faces é 10 °C. Qual é o fluxo de calor por condução?", "o": ["12 W", "24 W", "2 400 W", "12 000 W"], "a": 2, "h": "Φ = k·A·ΔT / L, com L em metros.", "e": "Φ = 0,8 · 1,5 · 10 / 0,005 = 12 / 0,005 = 2 400 W.", "c": 1, "n": 3, "x": {"0": "12 W esquece de dividir pela espessura L.", "1": "24 W usa L = 0,5 m em vez de 0,005 m.", "3": "12 000 W erra a conversão de milímetros para metros."}, "an": "calc_t096"}, {"id": "t097", "t": "cl", "q": "Um recipiente de capacidade térmica 50 cal/°C contém 250 g de água a 20 °C. O conjunto recebe 5 000 cal. Qual é, aproximadamente, a temperatura final? (c da água = 1 cal/g·°C)", "o": ["40 °C", "≈ 16,7 °C", "≈ 56,7 °C", "≈ 36,7 °C"], "a": 3, "h": "O calor aquece a água e o recipiente: Q = (m·c + C)·ΔT.", "e": "Capacidade total: 250·1 + 50 = 300 cal/°C. ΔT = 5 000/300 ≈ 16,7 °C. Tf = 20 + 16,7 ≈ 36,7 °C.", "c": 1, "n": 3, "x": {"0": "40 °C ignora o recipiente, que também esquenta.", "1": "16,7 °C é a variação de temperatura; falta somar a temperatura inicial.", "2": "56,7 °C soma a temperatura final à inicial, contando os 20 °C duas vezes."}, "an": "calc_t097"}, {"id": "t098", "an": "escalas", "t": "ct", "q": "Quem é o cientista desenhado na figura, que propôs a escala termométrica baseada nos pontos de fusão do gelo e de ebulição da água?", "o": ["Anders Celsius", "Daniel Fahrenheit", "Lord Kelvin", "James Joule"], "a": 0, "h": "Ele era sueco e astrônomo.", "e": "Anders Celsius (1701–1744) propôs, em 1742, a escala com 100 divisões entre os pontos fixos da água. A escala leva o nome dele.", "f": "ret_celsius", "x": {"1": "Fahrenheit criou outra escala, em que a água congela a 32 °F.", "2": "Kelvin propôs a escala absoluta.", "3": "Joule estudou a relação entre trabalho e calor."}, "n": 1}, {"id": "t099", "an": "escalas", "t": "ct", "q": "Quem é o cientista desenhado na figura, que construiu termômetros de mercúrio precisos e propôs a escala em que a água congela a 32 graus?", "o": ["Lord Kelvin", "Daniel Fahrenheit", "James Joule", "Joseph Black"], "a": 1, "h": "A escala usada nos Estados Unidos leva o nome dele.", "e": "Daniel Gabriel Fahrenheit (1686–1736) fabricou termômetros de mercúrio confiáveis e publicou sua escala em 1724. Depois da morte dele, a escala foi ajustada para 32 °F na fusão do gelo e 212 °F na ebulição da água.", "f": "ret_fahrenheit", "x": {"0": "Kelvin propôs a escala absoluta, em kelvins.", "2": "Joule não criou escala de temperatura.", "3": "Black não criou escala de temperatura."}, "n": 1}, {"id": "t100", "an": "escalas", "t": "ct", "q": "Quem é o cientista desenhado na figura, que propôs a escala absoluta de temperatura, cujo zero é o zero absoluto?", "o": ["James Joule", "Joseph Black", "Lord Kelvin", "Anders Celsius"], "a": 2, "h": "O nome verdadeiro dele era William Thomson.", "e": "William Thomson, Lord Kelvin (1824–1907), propôs em 1848 a ideia de uma escala absoluta de temperatura. A escala moderna, em que o zero é o zero absoluto e não há valores negativos, foi formulada por ele e Joule em 1854.", "f": "ret_kelvin", "x": {"0": "Joule mediu o equivalente mecânico do calor.", "1": "Black estudou o calor latente.", "3": "Celsius propôs a escala centígrada, não a absoluta."}, "n": 1}, {"id": "t101", "an": "joule_pa", "t": "ct", "q": "Quem é o cientista desenhado na figura, que mediu o equivalente mecânico do calor com uma pá giratória em água?", "o": ["Joseph Black", "Anders Celsius", "Daniel Fahrenheit", "James Joule"], "a": 3, "h": "A unidade de energia do SI leva o nome dele.", "e": "James Prescott Joule (1818–1889) mostrou que o trabalho mecânico aquece a água e que o calor é uma forma de energia. O joule é a unidade de energia do SI.", "f": "ret_joule", "x": {"0": "Black distinguiu calor e temperatura, mas não mediu o equivalente mecânico.", "1": "Celsius é lembrado pela escala centígrada.", "2": "Fahrenheit é lembrado pelos termômetros e pela escala."}, "n": 1}, {"id": "t102", "an": "estados", "t": "ct", "q": "Quem é o cientista desenhado na figura, que distinguiu calor de temperatura e descobriu o calor latente?", "o": ["Joseph Black", "Anders Celsius", "Daniel Fahrenheit", "Lord Kelvin"], "a": 0, "h": "Ele era escocês e viveu no século XVIII.", "e": "Joseph Black (1728–1799), químico e físico britânico, mostrou que calor e temperatura são grandezas diferentes e descobriu o calor latente, a energia absorvida na mudança de estado sem variar a temperatura.", "f": "ret_black", "x": {"1": "Celsius criou uma escala termométrica.", "2": "Fahrenheit fez termômetros e escala.", "3": "Kelvin propôs a escala absoluta."}, "n": 1}, {"id": "t103", "an": "escalas", "t": "ct", "q": "Verdadeiro ou falso: na escala Kelvin não existem valores negativos.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "O zero dessa escala é o zero absoluto.", "e": "O zero kelvin é o zero absoluto, a menor temperatura possível. Por isso a escala não tem valores negativos.", "v": 1, "x": {"1": "A afirmação é verdadeira: não há temperatura abaixo de 0 K."}, "n": 1}, {"id": "t104", "an": "escalas", "t": "ct", "q": "Verdadeiro ou falso: na escala Kelvin, o zero corresponde ao ponto de fusão do gelo.", "o": ["Verdadeiro", "Falso"], "a": 1, "h": "O ponto de fusão do gelo é 273 K, aproximadamente.", "e": "O zero kelvin é o zero absoluto (cerca de −273 °C). O gelo derrete em torno de 273 K, ou seja, 0 °C.", "v": 1, "x": {"0": "O zero kelvin é o zero absoluto, não o ponto de fusão do gelo. A afirmação é falsa."}, "n": 1}, {"id": "t105", "an": "joule_pa", "t": "ct", "q": "Verdadeiro ou falso: Joule mostrou que o trabalho mecânico pode aquecer a água, e que o calor é uma forma de energia.", "o": ["Verdadeiro", "Falso"], "a": 0, "h": "Pense na pá giratória dentro do recipiente.", "e": "Nos experimentos de Joule, um peso em queda girava uma pá dentro da água e a temperatura subia. Assim, trabalho mecânico se converte em calor.", "v": 1, "x": {"1": "A afirmação é verdadeira."}, "n": 1},{"id": "t106", "an": "calc_t106", "t": "cl", "q": "Uma panela contém 250 g de água a 20 °C. Qual a quantidade de calor necessária para aquecê-la até 80 °C? (calor específico da água: 1 cal/g·°C)", "o": ["15 000 cal", "5 000 cal", "20 000 cal", "1 500 cal"], "a": 0, "h": "Use Q = m · c · ΔT com a variação de temperatura, não a temperatura final.", "e": "ΔT = 80 − 20 = 60 °C. Q = m·c·ΔT = 250 · 1 · 60 = 15 000 cal (15 kcal).", "c": 1, "x": ["Usou só a temperatura final (80 °C) no lugar de ΔT.", "Usou ΔT = 20 °C.", "Errou a conta da multiplicação por 10."], "n": 2},{"id": "t107", "an": "calc_t107", "t": "cl", "q": "Um bloco de ferro de 400 g (c = 0,11 cal/g·°C) é aquecido de 20 °C a 120 °C. Que quantidade de calor ele recebe?", "o": ["4 400 cal", "440 cal", "44 000 cal", "5 280 cal"], "a": 0, "h": "O calor específico do ferro já é dado: aplique Q = m · c · ΔT.", "e": "ΔT = 120 − 20 = 100 °C. Q = 400 · 0,11 · 100 = 4 400 cal.", "c": 1, "x": ["Errou a casa decimal ao multiplicar por 0,11.", "Esqueceu de multiplicar por 100 °C no último passo.", "Usou ΔT = 120 °C."], "n": 2},{"id": "t108", "an": "calc_t108", "t": "cl", "q": "Um objeto de 200 g de cobre tem calor específico de 0,09 cal/g·°C. Qual é a capacidade térmica desse objeto?", "o": ["18 cal/°C", "2,2 cal/°C", "0,45 cal/°C", "1 800 cal/°C"], "a": 0, "h": "Capacidade térmica é o produto da massa pelo calor específico.", "e": "C = m · c = 200 · 0,09 = 18 cal/°C. Isso significa 18 cal para elevar o objeto em 1 °C.", "c": 1, "x": ["Dividiu a massa pelo calor específico.", "Dividiu o calor específico pela massa.", "Errou duas casas decimais."], "n": 2},{"id": "t109", "an": "calc_t109", "t": "me", "q": "Quanto calor é preciso para fundir totalmente 300 g de gelo a 0 °C? (calor latente de fusão do gelo: 80 cal/g)", "o": ["24 000 cal", "3,75 cal", "240 cal", "2 400 cal"], "a": 0, "h": "Durante a mudança de estado não há ΔT: use Q = m · L.", "e": "Na fusão a temperatura não muda; usa-se Q = m · L = 300 · 80 = 24 000 cal (24 kcal).", "c": 1, "x": ["Dividiu a massa pelo calor latente.", "Errou por fator 100.", "Errou por fator 10."], "n": 2},{"id": "t110", "an": "calc_t110", "t": "me", "q": "Qual a quantidade de calor para vaporizar 50 g de água que já está a 100 °C? (calor latente de vaporização: 540 cal/g)", "o": ["27 000 cal", "10,8 cal", "2 700 cal", "5 400 cal"], "a": 0, "h": "Água já a 100 °C: não há aquecimento, só mudança de estado.", "e": "A água já está na temperatura de ebulição, então só há mudança de estado: Q = m · L = 50 · 540 = 27 000 cal.", "c": 1, "x": ["Dividiu a massa pelo calor latente.", "Errou por fator 10.", "Errou por fator 5."], "n": 2},{"id": "t111", "an": "calc_t111", "t": "dl", "q": "Um líquido ocupa 500 cm³ a 20 °C e tem coeficiente de dilatação volumétrica de 1,0·10⁻³ °C⁻¹. De quanto aumenta seu volume ao ser aquecido até 60 °C?", "o": ["20 cm³", "2 cm³", "200 cm³", "0,5 cm³"], "a": 0, "h": "Use ΔV = V₀ · γ · ΔT.", "e": "ΔT = 60 − 20 = 40 °C. ΔV = V₀ · γ · ΔT = 500 · 1,0·10⁻³ · 40 = 20 cm³.", "c": 1, "x": ["Errou a potência de dez do coeficiente.", "Usou ΔT = 4 °C.", "Dividiu em vez de multiplicar."], "n": 2}];